Let $q \in [1,3)$ and let $H$ be a fixed connected planar graph on the vertices $\{1, \ldots ,h\}$, 
with the extra condition that $H$ is a tree if $ q=1$.
Then there exists $\alpha= \alpha(H,q)>0$ such that 
\begin{displaymath}
\mathbf{P} \left[f_{H} \left( P_{n, \lfloor qn \rfloor} \right) \leq \alpha n \right] = e^{- \Omega (n)}. 
\end{displaymath}

Let $H$ be a fixed connected planar graph on the vertices $\{1,2, \ldots ,h\}$,
let $b>1$ and $B<3$ be given constants,
and let $m=m(n) \in [bn,Bn]$ $\forall n$.
Then there exist constants $N(H,b,B)$ and $\alpha(H,b,B) >0$ such that
\begin{displaymath}
\mathbf{P}[f_{H}(P_{n,m}) \leq \alpha n] < e^{- \alpha n} \textrm{ } \forall n \geq N.
\end{displaymath}

Let $c>0$ and $\delta<1/8$ be given constants and let $m=m(n) \in [cn, (1+\delta)n]$ for all large $n$. 
Then there exists a constant $\beta(c,\delta) >0$ such that 
\begin{displaymath}
\mathbf{P}[P_{n,m} \textrm{ will have } < \beta n \textrm{ vertices of degree } 1] < e^{-\beta n} 
\textrm{ for all large } n.
\end{displaymath}

Let $b>0$ and $B<3$ be given constants and 
let $m(n) \in [bn,Bn]$ for all large $n$.
Then there exists a constant $\alpha(b,B) > 0$ such that
\begin{displaymath}
\mathbf{P}[P_{n,m} \textrm{ will have } < \alpha n \textrm{ pendant edges }] < e^{- \alpha n} 
\textrm{ for all large } n.
\end{displaymath}

Let $d = d(n)>0$ be such that $d=\Omega(n^{1/2})$ and $\limsup \frac{d}{n}<2$. 
Then 
\begin{displaymath}
\emph{add}(n,n+d) = \Omega \left( \frac{n^{2}}{d} \right). 
\end{displaymath}

Let $\lambda$ be a (not necessarily positive) fixed constant and 
let $m=m(n)$ be such that $m \leq n + \lambda n^{1/2} + o(n^{1/2})$. 
Then
\begin{displaymath}
\emph{add}(n,m) \geq (1+o(1))
\left\{ \begin{array}{ll}
\left( 2 - \lambda \right) n^{3/2} & \textrm{if } \lambda \leq 1 \\
\frac{1}{\lambda} n^{3/2} & \textrm{if } \lambda \geq 1 \\
\end{array} \right. 
\end{displaymath}
}

Let $n \geq 6$ and let $m \geq 8$.
Then 
\begin{displaymath}
\emph{add}(n,m) \geq \left \lceil \frac{3}{2} (3n-6-m) \right \rceil.
\end{displaymath}

Let $d = d(n)>0$ be such that $d=\omega(n^{1/2})$ and $d=o(n)$. 
Then 
\begin{displaymath}
\emph{add}(n,n+d) \geq \frac{n^{2}}{d} + O(n). 
\end{displaymath}

Let $m=m(n) \leq (1+o(1))n$.
Then 
\begin{displaymath}
\emph{add}(n,m)=\omega(n).
\end{displaymath}

Let $d=d(n)>0$ be such that $d= \Omega(n^{1/2})$.
Then 
\begin{displaymath}
\emph{add}(n,n-d) =O(dn).
\end{displaymath}

Let $m \geq 2n-3$.
Then 
\begin{displaymath}
\emph{add}(n,m) \leq \left \lceil \frac{3}{2} (3n-6-m) \right \rceil.
\end{displaymath}

Let $m=m(n)$. 
Then 
\begin{displaymath}
\emph{add}(n,m) \geq \frac{(n+m)(n-m-1)}{2}.
\end{displaymath}

Let $d=d(n)>0$ be such that $d= \Omega(n^{1/2})$.
Then 
\begin{displaymath}
\emph{add}(n,n-d) =\Omega(dn).
\end{displaymath}

Let $d=d(n)>0$ be such that $d=\Omega(n^{1/2})$ and $d=o(n)$.
Then 
\begin{displaymath}
\emph{add}(n,n-d) \geq (1+o(1)) dn. 
\end{displaymath}

Let $A < 1$ be a fixed constant and let $m(n)$ be such that~$m \leq~\!An$ for all large $n$.
Then 
\begin{displaymath}
\emph{add}(n,m) \geq (1+o(1)) \frac{(1-A)(1+A)}{2} n^{2}. 
\end{displaymath}

Let $b>1$ and $B<3$ be fixed constants and let $m(n) \in [bn,Bn]$ for all large $n$.
Let $H_{1},H_{2}, \ldots, H_{l}$ 
be (fixed) connected planar graphs and let $t$ be a fixed constant.
Then there exist constants $\epsilon > 0$ and $N$ such that
\begin{eqnarray*}
& & \mathbf{P} 
\Big[ \bigcap_{i=1}^{l} 
(
\textrm{$P_{n,m}$
will have $\geq t$ components with} \\
& & \phantom{wwwww}\textrm{an order-preserving isomorphism to $H_{i}$} ) ] 
\geq \epsilon \textrm{ } \forall n \geq N.  
\end{eqnarray*}

Let $c>0$ and $B<3$ be fixed constants and let $m(n) \in [cn,Bn]$ for all large $n$.
Let $H_{1},H_{2}, \ldots, H_{l}$ 
be (fixed) connected planar graphs with at most one cycle each and let $t$ be a fixed constant.
Then there exist constants $\epsilon > 0$ and $N$ such that
\begin{eqnarray*}
& & \mathbf{P} 
\Big[ \bigcap_{i=1}^{l} 
(
\textrm{$P_{n,m}$
will have $\geq t$ components with} \\
& & \phantom{wwwww}\textrm{an order-preserving isomorphism to $H_{i}$} ) ] 
\geq \epsilon \textrm{ } \forall n \geq N.
\end{eqnarray*}

Let $b>1$ and $B<3$ be fixed constants and let $m(n) \! \in \! [bn,Bn]$~$\! \forall n$.
Then there exist constants $N(b,B)$ and $\delta (b,B) >0$ such that
\begin{displaymath}
\mathbf{P}[P_{n,m} \textrm{ will have $< \delta n$ edge-disjoint appearances of } K_{4}] < 
e^{- \delta n} \textrm{ } \forall n \geq N.
\end{displaymath}

Let $b>0$ and $B<3$ be given constants and 
let $m(n) \in [bn,Bn]$ for all large $n$.
Then there exists a constant $\alpha(b,B) > 0$ such that
\begin{displaymath}
\mathbf{P}[P_{n,m} \textrm{ will have } < \alpha n \textrm{ pendant edges }] < e^{- \alpha n} 
\textrm{ for all large } n.
\end{displaymath}

Let $H$ be a fixed connected planar graph on the vertices $\{1,2, \ldots ,h\}$,
let $b>1$ and $B<3$ be given constants,
and let $m=m(n) \in [bn,Bn]$ $\forall n$.
Then there exist constants $N(H,b,B)$ and $\alpha(H,b,B) >0$ such that
\begin{displaymath}
\mathbf{P}[f_{H}(P_{n,m}) \leq \alpha n] < e^{- \alpha n} \textrm{ } \forall n \geq N.
\end{displaymath}

Let $m=m(n) \leq (1+o(1))n$.
Then 
\begin{displaymath}
\emph{add}(n,m)=\omega(n).
\end{displaymath}

Let $H$ be a (fixed) tree, let $t$ and $c>0$ be fixed constants and let $m=m(n) \in [cn, (1+o(1))n]$ as $n \to \infty$.
Then
\begin{eqnarray*}
\mathbf{P}[P_{n,m} \textrm{ will have } \geq t \textrm{ components with an order-preserving isomorphism to } H] \\
\to 1 \textrm{ as } n \to \infty.
\end{eqnarray*}

Let $m=m(n) \in [n,3n-6]$ for all large $n$.
Then
\begin{displaymath}
\liminf_{n \to \infty} \left( \frac{|\mathcal{P}(n,m)|}{n!} \right)^{1/n} \geq \gamma (1) = e.
\end{displaymath}

\begin{eqnarray*}
|\mathcal{P}(n)| \sim g \cdot n^{-7/2} \gamma_{l}^{n}n! ,
\end{eqnarray*}
where $g \approx 0.4260938569 \cdot 10^{-5}$
and $\gamma_{l} \approx 27.2268777685$ are constants given by explicit analytic expressions.

Let $m=m(n) \in [n,3n-6]$ for all large $n$ and let the constant $c$ satisfy $c> \ln \gamma_{l} - 1$.
Then
\begin{displaymath}
\mathbf{P} \left[ \kappa (P_{n,m}) > \left \lceil \frac{cn}{\ln n} \right \rceil \right] = e^{- \Omega(n)}.
\end{displaymath}

Let $m=m(n) \in [qn,n-1]$ for some fixed $q \in (0,1)$
and let the constant $c$ satisfy $c> \ln \left( \frac{\gamma _{l}}{q} \right) + e^{-1}$.
Then
\begin{displaymath}
\mathbf{P} \left[ \kappa (P_{n,m}) > \left \lceil \frac{cn}{\ln n} + n-m \right \rceil \right] = e^{- \Omega(n)}.
\end{displaymath}

Let $H$ be a fixed connected planar graph on the vertices $\{1,2, \ldots ,h\}$,
let $b>1$ and $B<3$ be given constants,
and let $m=m(n) \in [bn,Bn]$ $\forall n$.
Then there exist constants $N(H,b,B)$ and $\alpha(H,b,B) >0$ such that
\begin{displaymath}
\mathbf{P}[f_{H}(P_{n,m}) \leq \alpha n] < e^{- \alpha n} \textrm{ } \forall n \geq N.
\end{displaymath}

Let $b>1$ and $B<3$ be fixed constants and let $m(n) \in [bn,Bn]$~$\forall n$.
Then $\exists c(b,B)>0$ such that 
\begin{displaymath}
\mathbf{P}[P_{n,m} \textrm{ will be connected}] \geq c \textrm{ } \forall n.
\end{displaymath}

Let $C \in \left( \frac{41}{14},3 \right]$ and let $m=m(n) \in [Cn-o(n), 3n-6]$.
Then
\begin{displaymath}
\limsup _{n \to \infty} \mathbf{P}[P_{n,m} \textrm{ will \emph{not} be connected}] 
\leq \frac{15(3-C)}{\frac{2}{7} - 12 + 4C}.
\end{displaymath}

Let $b>1$ and let $m=m(n) \in [bn, 3n-6]$. Then $\exists c(b) > 0$ such that 
\begin{displaymath}
\mathbf{P}[P_{n,m} \textrm{ will be connected}] > c \textrm{  } \forall n.
\end{displaymath}

Let $m=m(n)$ satisfy 
$1 < \liminf_{n \to \infty} \frac{m}{n} \leq \limsup_{n \to \infty} \frac{m}{n} < 3$.
Then there exists a constant $K$ such that
\begin{displaymath}
\mathbf{E}[\kappa (P_{n,m})] < K \textrm{ } \forall n.
\end{displaymath}

Let $C \in (\frac{41}{14},3]$ and let $m=m(n) \in [Cn-o(n), 3n-6]$.
Then there exists a constant $K$ such that
\begin{displaymath}
\mathbf{E}[\kappa (P_{n,m})] < K \textrm{ } \forall n.
\end{displaymath}

Let $m=m(n)$ satisfy $\liminf_{n \to \infty} \frac{m}{n} > 1$.
Then there exists a constant $K$ such that
\begin{displaymath}
\mathbf{E}[\kappa (P_{n,m})] < K \textrm{ } \forall n.
\end{displaymath}

Let $m=m(n) \leq (1+o(1))n$.
Then 
\begin{displaymath}
\emph{add}(n,m)=\omega(n).
\end{displaymath}

Let $m \leq (1+o(1))n$ and let $H$ be a (fixed) multicyclic connected planar graph.
Then
\begin{displaymath}
\mathbf{P}[P_{n,m} \textrm{ will have a component isomorphic to } H] \to 0 \textrm{ as } n \to \infty.
\end{displaymath}

Let $k$ be a fixed constant.
Then, given any $m(n)$,
\begin{displaymath}
\limsup_{n \to \infty}
\mathbf{P}[P_{n,m} \textrm{ will contain any unicyclic components of order } \leq k] < 1.
\end{displaymath}

Let $b>1$ and let $m=m(n) \in [bn, 3n-6]$. Then $\exists c(b) > 0$ such that 
\begin{displaymath}
\mathbf{P}[P_{n,m} \textrm{ will be connected}] > c \textrm{  } \forall n.
\end{displaymath}

Let $k$ be a fixed constant.
Then, given any $m(n)$,
\begin{displaymath}
\limsup_{n \to \infty}
\mathbf{P}[P_{n,m} \textrm{ will contain any non-acyclic components of order } \leq k] < 1.
\end{displaymath}

Let $H$ be a fixed connected planar graph on the vertices $\{1,2, \ldots ,h\}$,
let $b>1$ and $B<3$ be given constants,
and let $m=m(n) \in [bn,Bn]$ $\forall n$.
Then there exist constants $N(H,b,B)$ and $\alpha(H,b,B) >0$ such that
\begin{displaymath}
\mathbf{P}[f_{H}(P_{n,m}) \leq \alpha n] < e^{- \alpha n} \textrm{ } \forall n \geq N.
\end{displaymath}

Let $H$ be a fixed connected planar graph on the vertices $\{1,2, \ldots ,h\}$,
let $b>1$ and $B<3$ be given constants,
and let $m=m(n) \in [bn,Bn]$ $\forall n$.
Then there exist constants $N(H,b,B)$ and $\beta(H,b,B) >0$ such that
\begin{displaymath}
\mathbf{P}[f_{H}^{\prime}(P_{n,m}) \leq \beta n] < e^{- \beta n} \textrm{ } \forall n \geq N.
\end{displaymath}

Let $H$ be a (fixed) tree, let $t$ and $c>0$ be fixed constants and let $m=m(n) \in [cn, (1+o(1))n]$ as $n \to \infty$.
Then
\begin{eqnarray*}
\mathbf{P}[P_{n,m} \textrm{ will have } \geq t \textrm{ components with an order-preserving isomorphism to } H] \\
\to 1 \textrm{ as } n \to \infty.
\end{eqnarray*}

Let $H$ be a (fixed) planar graph and let $m=m(n)$ satisfy \\
$1 < \liminf_{n \to \infty} \frac{m}{n} \leq \limsup_{n \to \infty} \frac{m}{n} < 3$.
Then $\exists \alpha > 0$ and $\exists N$ such that
\begin{eqnarray*}
& & \mathbf{P}\Big[\textrm{$P_{n,m}$
will \emph{not} have a set of $\geq \alpha n$ vertex-disjoint} \\
& & \phantom{wwwwwwwwi}\textrm{induced order-preserving copies of $H$}\Big] 
< e^{- \alpha n} 
\textrm{ } \forall n \geq N.
\end{eqnarray*}

Let $H$ be a (fixed) planar graph and let $\liminf_{n \to \infty} \frac{m}{n} > 1$.
Then $\exists \alpha > 0$ and $\exists N$ such that
\begin{eqnarray*}
& & \mathbf{P}\Big[\textrm{$P_{n,m}$
will \emph{not} have a set of $> \alpha n$ vertex-disjoint} \\
& & \phantom{wwwwwwwwi}\textrm{induced order-preserving copies of $H$}\Big] 
< e^{- \alpha n} 
\textrm{ } \forall n \geq N. \\
\end{eqnarray*}

Let $d=d(n)>0$ be such that $d= \Omega(n^{1/2})$.
Then 
\begin{displaymath}
\emph{add}(n,n-d) =\Omega(dn).
\end{displaymath}

Let $m=m(n) \in [n,3n-6]$ for all large $n$ and let the constant $c$ satisfy $c> \ln \gamma_{l} - 1$.
Then
\begin{displaymath}
\mathbf{P} \left[ \kappa (P_{n,m}) > \left \lceil \frac{cn}{\ln n} \right \rceil \right] = e^{- \Omega(n)}.
\end{displaymath}

Let $m=m(n) \in [qn,n-1]$ for some fixed $q \in (0,1)$
and let the constant $c$ satisfy $c> \ln \left( \frac{\gamma _{l}}{q} \right) + e^{-1}$.
Then
\begin{displaymath}
\mathbf{P} \left[ \kappa (P_{n,m}) > \left \lceil \frac{cn}{\ln n} + n-m \right \rceil \right] = e^{- \Omega(n)}.
\end{displaymath}

Let $k$ be a fixed constant and let $m=m(n) \leq An$, where $A<1$.
Then
\begin{displaymath}
\limsup_{n \to \infty}
\mathbf{P}[P_{n,m} \textrm{ will have girth }\leq k] < 1.
\end{displaymath}

Let $H$ be a (fixed) connected unicyclic graph,
let $t$ be a fixed constant,
and let $m=m(n) \in [(1-o(1))n, Bn]$, where $B<3$.
Then
\begin{displaymath}
\mathbf{P}[f^{\prime}_{H}(P_{n,m}) \geq t] \to 1 
\textrm{ as } n \to \infty.
\end{displaymath}

Let $H$ be a (fixed) planar graph and let $\liminf_{n \to \infty} \frac{m}{n} > 1$.
Then $\exists \alpha > 0$ and $\exists N$ such that
\begin{eqnarray*}
& & \mathbf{P}\Big[\textrm{$P_{n,m}$
will \emph{not} have a set of $> \alpha n$ vertex-disjoint} \\
& & \phantom{wwwwwwwwi}\textrm{induced order-preserving copies of $H$}\Big] 
< e^{- \alpha n} 
\textrm{ } \forall n \geq N. \\
\end{eqnarray*}

Let $b>0$ and $B<3$ be given constants and 
let $m(n) \in [bn,Bn]$ for all large $n$.
Then there exists a constant $\alpha(b,B) > 0$ such that
\begin{displaymath}
\mathbf{P}[P_{n,m} \textrm{ will have } < \alpha n \textrm{ pendant edges }] < e^{- \alpha n} 
\textrm{ for all large } n.
\end{displaymath}

Let $d=d(n)>0$ be such that $d= \Omega(n^{1/2})$.
Then 
\begin{displaymath}
\emph{add}(n,n-d) =\Omega(dn).
\end{displaymath}

Let $\lambda$ be a (not necessarily positive) fixed constant and 
let $m=m(n)$ be such that $m \leq n + \lambda n^{1/2} + o(n^{1/2})$. 
Then
\begin{displaymath}
\emph{add}(n,m) \geq (1+o(1))
\left\{ \begin{array}{ll}
\left( 2 - \lambda \right) n^{3/2} & \textrm{if } \lambda \leq 1 \\
\frac{1}{\lambda} n^{3/2} & \textrm{if } \lambda \geq 1 \\
\end{array} \right. 
\end{displaymath}
}

Let $d = d(n)>0$ be such that $d=\Omega(n^{1/2})$ and $\limsup \frac{d}{n}<2$. 
Then 
\begin{displaymath}
\emph{add}(n,n+d) = \Omega \left( \frac{n^{2}}{d} \right). 
\end{displaymath}

Let $H$ be a fixed multicyclic connected planar graph
and let $d=d(n)=n-m$ be such that $d>0$ and $d = \omega \left( n^{\frac{|H|}{e(H)}} \right)$.
Then 
\begin{displaymath}
\mathbf{P}[P_{n,m} \textrm{ will have a copy of }H] \to 0 \textrm{ as } n \to \infty.
\end{displaymath}

Let $H$ be a fixed connected planar graph such that $e(H) > 2|H|$
and let $m=m(n)$ be such that $\max \{ 0,m-n \} = o \left( n^{1- \frac{|H|}{e(H)}} \right)$.
Then 
\begin{displaymath}
\mathbf{P}[P_{n,m} \textrm{ will have a copy of }H] \to 0 \textrm{ as } n \to \infty.
\end{displaymath}

There exists a constant $c >0$ such that,
given any constants $r,d_{1},D_{2} \in \mathbf{N} \cup \{ 0 \}$ with $D_{2} \geq 3$
and $\mathcal{P}(r,d_{1},5,0,D_{2}) \neq \emptyset$,
\begin{displaymath}
\mathbf{P} [P_{r,d_{1},5,0,D_{2}} \textrm{ will be connected}] > c.
\end{displaymath}

There exists a constant $c >0$ such that,
given any constants $r,d_{1},D_{2} \in \mathbf{N} \cup \{ 0 \}$ with $D_{2} \geq 3$
and $\mathcal{P}(r,d_{1},5,0,D_{2}) \neq \emptyset$,
\begin{displaymath}
\mathbf{P} [P_{r,d_{1},5,0,D_{2}} \textrm{ will be connected}] > c.
\end{displaymath}

Let $d_{1} \in \{ 0,1, \ldots, 5 \}$ be a constant and 
let $D_{2}(n)$ be a monotonically non-decreasing integer-valued function that for all large $n$ satisfies
$D_{2}(n) \geq \max \{ d_{1}, 3 \}$ and $(d_{1},D_{2}(n)) \notin \{ (3,3), (5,5) \}$.
Then there exists a \emph{finite} constant $\gamma_{d_{1},D_{2}} >0$ such that
\begin{displaymath}
\left( \frac{|\mathcal{P}(n,d_{1},5,0,D_{2})|}{n!} \right)^{\frac{1}{n}} \to 
\gamma_{d_{1},D_{2}} 
\textrm{ as } n \to \infty.
\end{displaymath}

Let $D_{2} \in \{ 3,5 \}$ be a fixed constant.
Then there is a finite constant $\gamma_{D_{2},D_{2}}>0$ such that
\begin{displaymath}
\left( \frac{|\mathcal{P}(2n,D_{2},5,0,D_{2})|}{(2n)!} \right)^{\frac{1}{2n}} \to 
\gamma_{D_{2},D_{2}} \textrm{ as } n \to \infty.
\end{displaymath}

Let $d_{1} \in \{ 0,1, \ldots, 5 \}$ be a constant and 
let $D_{2}(n)$ be a monotonically non-decreasing integer-valued function that for all large $n$ satisfies
$D_{2}(n) \geq \max \{ d_{1}, 3 \}$ and $(d_{1},D_{2}(n)) \notin \{ (3,3), (5,5) \}$.
Then there exists a \emph{finite} constant $\gamma_{d_{1},D_{2}} >0$ such that
\begin{displaymath}
\left( \frac{|\mathcal{P}(n,d_{1},5,0,D_{2})|}{n!} \right)^{\frac{1}{n}} \to 
\gamma_{d_{1},D_{2}} 
\textrm{ as } n \to \infty.
\end{displaymath}

Let $D_{2} \in \{ 3,5 \}$ be a fixed constant.
Then there is a finite constant $\gamma_{D_{2},D_{2}}>0$ such that
\begin{displaymath}
\left( \frac{|\mathcal{P}(2n,D_{2},5,0,D_{2})|}{(2n)!} \right)^{\frac{1}{2n}} \to 
\gamma_{D_{2},D_{2}} \textrm{ as } n \to \infty.
\end{displaymath}

Let $D_{2} \geq 3$ be a fixed constant, 
let $H$ be an $D_{2}$-regular connected planar graph on $\{ 1,2, \ldots,h \}$
and let $f \in E(H)$ be a non cut-edge.
Then $\exists \alpha >0$ and $\exists N$ such that
\begin{eqnarray*}
& & \mathbf{P}[P_{n,D_{2},5,0,D_{2}} \textrm{ will have } \leq \alpha n \textrm{ $2$-appearances of } H \setminus f] \\
& & \phantom{wwwwwwwwwwwwwwwww} < e^{- \alpha n} 
\left \{ \begin{array}{ll}
\forall n \geq N \textrm{ if } D_{2}=4 \\
\textrm{for all even } n \geq N \textrm{ if } D_{2} \in \{ 3,5 \}.
\end{array} \right.
\end{eqnarray*}
}

Let $H$ be a fixed connected planar graph on $\{ 1,2, \ldots, h \}$.
Then $\exists \alpha (h) \!>\!0$ such that,
given any integer-valued functions $d_{1}(n)$ and $D_{2}(n)$ satisfying
$\limsup_{n \to \infty}\!d_{1}(n) \!\leq\! \delta(H)$ 
and $\liminf_{n \to \infty}\!D_{2}(n) \!\geq\! \max \{\Delta(H), \deg_{\!H}\!(1)+~\!1, 3 \},$
we have
\begin{displaymath}
\mathbf{P} [ f_{H}^{d_{1}} (P_{n,d_{1},5,0,D_{2}}) \leq \alpha n ] < e^{-\alpha n} 
\textrm{ for all sufficiently large } n.
\end{displaymath}

Let $D_{2} \geq 3$ be a fixed constant, 
let $H$ be a $D_{2}$-regular connected planar graph on $\{1,2, \ldots,h \}$,
and let $f \in E(H)$ be a non cut-edge.
Then $\exists \beta$ and $\exists N$ such that
\begin{eqnarray*}
& & \mathbf{P}\Big[\textrm{$P_{n,D_{2},5,0,D_{2}}$ 
will not have a set of $\geq \beta n$ 
totally} \\
& & \phantom{wwwwwwq}\textrm{vertex-disjoint $2$-appearances of $H \setminus f$}\Big] \\
& & \phantom{wwwwwwwwwwwwwww}< e^{- \beta n} 
\left \{ \begin{array}{ll}
\forall n \geq N \textrm{ if } D_{2}=4 \\
\textrm{for all even } n \geq N \textrm{ if } D_{2} \in \{ 3,5 \}.
\end{array} \right.
\end{eqnarray*}
}

Let $H$ be a fixed connected planar graph on $\{ 1,2, \ldots, h \}$.
Then $\exists \beta(H)\!>\!0$ such that,
given any integer-valued functions $d_{1}(n)$ and $D_{2}(n)$ satisfying
$\limsup_{n \to \infty} \!d_{1}(n) \!\leq\! \delta(H)$
and $\liminf_{n \to \infty} \!D_{2}(n) \!\geq\! \max \{ \Delta(H), \deg_{\!H}\!(1)+~\!1, 3 \},$
we have
\begin{displaymath}
\mathbf{P}[\widehat{f_{H}^{d_{1}}}(P_{n,d_{1},5,0,D_{2}}) \leq \beta n] < e^{- \beta n} 
\textrm{ for all sufficiently large } n.
\end{displaymath}

Let $H$ be a fixed connected planar graph on $\{ 1,2, \ldots, h \}$.
Then $\exists \beta(H)\!>\!0$ such that,
given any integer-valued functions $d_{1}(n)$ and $D_{2}(n)$ satisfying
